package net.officefloor.hq.app.statement;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.SignedInUser;
import net.officefloor.hq.app.claim.ClaimController.ClaimView;
import org.springframework.http.HttpStatus;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.DeleteMapping;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/sheets/{sheetId}")
@Validated
public class StatementController {

    /** What the screen shows of a person's statements: how many were taken, and the last one's
     *  due-total (two decimals, or n/a) and its date: the date it was taken as of, else the sheet's today
     *  when it was taken. */
    public record StatementView(long personId, int count, String lastDueTotal, LocalDate lastDate) {
        static StatementView of(StatementService.Summary summary) {
            Statement last = summary.last();
            return new StatementView(summary.personId(), summary.count(),
                    last.getDueTotal() == null ? "n/a" : last.getDueTotal().toPlainString(), last.getStatedOn());
        }
    }

    /** A statement just taken: the person's statements after it, and their claims as it bound them. */
    public record TakenView(StatementView statement, List<ClaimView> claims) {
    }

    /** A statement just cancelled: the person's statements after it (none when none is left), and their
     *  claims, live again. */
    public record CancelledView(StatementView statement, List<ClaimView> claims) {
    }

    /** What a statement is taken as of: a date on or before the sheet's today; none takes it now. */
    public record TakeForm(LocalDate asOf) {
    }

    private final StatementService service;

    public StatementController(StatementService service) {
        this.service = service;
    }

    /** The statements of each person on the sheet who has had one taken. */
    @GetMapping("/statements")
    public List<StatementView> list(@PathVariable @NotBlank @Size(max = 100) String sheetId) {
        return service.list(sheetId.trim()).stream().map(StatementView::of).toList();
    }

    /** Take a person's statement, now or as of a date. */
    @PostMapping("/people/{personId}/statements")
    @ResponseStatus(HttpStatus.CREATED)
    public TakenView take(@PathVariable @NotBlank @Size(max = 100) String sheetId, @PathVariable long personId,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user, @RequestBody(required = false) TakeForm form) {
        StatementService.Taken taken = service.take(sheetId.trim(), SignedInUser.name(user), personId,
                form == null ? null : form.asOf());
        return new TakenView(StatementView.of(taken.summary()),
                taken.claims().stream().map(ClaimView::of).toList());
    }

    /** Cancel a person's last statement; a steward only. */
    @DeleteMapping("/people/{personId}/statements/last")
    public CancelledView cancel(@PathVariable @NotBlank @Size(max = 100) String sheetId, @PathVariable long personId,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user) {
        StatementService.Cancelled cancelled = service.cancel(sheetId.trim(), SignedInUser.name(user), personId);
        return new CancelledView(cancelled.summary() == null ? null : StatementView.of(cancelled.summary()),
                cancelled.claims().stream().map(ClaimView::of).toList());
    }
}
package net.officefloor.hq.app.statement;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;

/** A statement taken of a person: their due-total at that moment, or as of the date it was taken as of,
 *  and how many claims counted. */
@Entity
@Table(name = "statement")
public class Statement {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "person_id", nullable = false)
    private Long personId;

    /** The person's due-total when the statement was taken; none when it was n/a. */
    @Column(name = "due_total", precision = 12, scale = 2)
    private BigDecimal dueTotal;

    @Column(name = "claims", nullable = false)
    private int claims;

    /** The sheet's today when the statement was taken. */
    @Column(name = "taken_on", nullable = false)
    private LocalDate takenOn;

    /** The statement's date: the date it was taken as of, else the sheet's today when it was taken. */
    @Column(name = "stated_on", nullable = false)
    private LocalDate statedOn;

    @Column(name = "taken_by", nullable = false)
    private String takenBy;

    /** Whether a merge or a transfer carried the statement to the person from another: it counts among
     *  their statements, but is their last only when they have none of their own. */
    @Column(name = "carried", nullable = false)
    private boolean carried;

    protected Statement() {
    }

    public Statement(String sheetId, Long personId, BigDecimal dueTotal, int claims, LocalDate takenOn,
            LocalDate statedOn, String takenBy) {
        this.sheetId = sheetId;
        this.personId = personId;
        this.dueTotal = dueTotal;
        this.claims = claims;
        this.takenOn = takenOn;
        this.statedOn = statedOn;
        this.takenBy = takenBy;
    }

    /** Carry the statement to the person a merge folds its person into; carried unless that person has
     *  no statement of their own, when it stays as it was. */
    public void carryTo(Long otherPersonId, boolean asCarried) {
        this.personId = otherPersonId;
        this.carried = carried || asCarried;
    }

    /** A copy of the statement for a person on another sheet, as a transfer takes it. */
    public Statement copyTo(String otherSheetId, Long otherPersonId) {
        Statement copy = new Statement(otherSheetId, otherPersonId, dueTotal, claims, takenOn, statedOn, takenBy);
        copy.carried = carried;
        return copy;
    }

    public boolean isCarried() {
        return carried;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public Long getPersonId() {
        return personId;
    }

    public BigDecimal getDueTotal() {
        return dueTotal;
    }

    public int getClaims() {
        return claims;
    }

    public LocalDate getTakenOn() {
        return takenOn;
    }

    public LocalDate getStatedOn() {
        return statedOn;
    }

    public String getTakenBy() {
        return takenBy;
    }
}
package net.officefloor.hq.app.statement;

import java.util.List;
import org.springframework.data.jpa.repository.JpaRepository;

public interface StatementRepository extends JpaRepository<Statement, Long> {

    /** The sheet's statements in the order they were taken. */
    List<Statement> findBySheetIdOrderByIdAsc(String sheetId);

    /** Drop the person's statements. */
    void deleteBySheetIdAndPersonId(String sheetId, Long personId);

    /** The person's statements in the order they were taken. */
    List<Statement> findBySheetIdAndPersonIdOrderByIdAsc(String sheetId, Long personId);
}
package net.officefloor.hq.app.statement;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimBinding;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.ClaimService;
import net.officefloor.hq.app.claim.ClaimStatus;
import net.officefloor.hq.app.claim.LateCharge;
import net.officefloor.hq.app.person.Grade;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateService;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.setting.DatedSettings;
import net.officefloor.hq.app.setting.Role;
import net.officefloor.hq.app.setting.SettingService;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

@Service
public class StatementService {

    /** A person's statements: how many were taken, and the last one (none when none was). */
    public record Summary(long personId, int count, Statement last) {
    }

    /** A statement just taken: the person's summary after it, and their claims as it bound them, newest first. */
    public record Taken(Summary summary, List<Claim> claims) {
    }

    private final StatementRepository statements;
    private final PersonRepository people;
    private final ClaimRepository claims;
    private final ClaimService claimService;
    private final RateService rates;
    private final SheetService sheets;
    private final Rollup rollup;
    private final SettingService settings;
    private final Audit audit;

    public StatementService(StatementRepository statements, PersonRepository people, ClaimRepository claims,
            ClaimService claimService, RateService rates, SheetService sheets, Rollup rollup, SettingService settings,
            Audit audit) {
        this.statements = statements;
        this.people = people;
        this.claims = claims;
        this.claimService = claimService;
        this.rates = rates;
        this.sheets = sheets;
        this.rollup = rollup;
        this.settings = settings;
        this.audit = audit;
    }

    /** The statement summary of each person on the sheet who has had a statement taken. */
    @Transactional(readOnly = true)
    public List<Summary> list(String sheetId) {
        Map<Long, Summary> by = new LinkedHashMap<>();
        for (Statement s : statements.findBySheetIdOrderByIdAsc(sheetId)) {
            Summary was = by.get(s.getPersonId());
            by.put(s.getPersonId(), was == null ? new Summary(s.getPersonId(), 1, s)
                    : new Summary(s.getPersonId(), was.count() + 1, later(was.last(), s)));
        }
        return List.copyOf(by.values());
    }

    /** A person's summary from their statements in the order they were taken; none when they have none. */
    private static Summary summarise(long personId, List<Statement> all) {
        Statement last = null;
        for (Statement s : all) last = last == null ? s : later(last, s);
        return last == null ? null : new Summary(personId, all.size(), last);
    }

